def full_cost(pkg, bank, case, sid, prof, q_price):
    """(full cost per unit, confidence): own-plant should-cost (high), a generic estimate scaled
    to the supplier's country (medium), else a share of its quote (low). A bundle has none."""
    parts = case.get("parts") or []
    if len(parts) != 1:
        return q_price * QUOTE_FLOOR, "low"
    rows = [
        {**r, "unit_cost": per_piece(r, "unit_cost")}
        for r in q(pkg, "SELECT supplier_id, unit_cost, price_unit FROM should_cost WHERE part_id = ?", (parts[0],))
    ]
    for ref in bank.ids("cost:"):  # the case's own facts (no table rows)
        f = bank.fact(ref)
        if f and f.get("part") == parts[0] and f.get("unit_cost"):
            rows.append({"supplier_id": f.get("supplier"), "unit_cost": f["unit_cost"]})
    own = [r for r in rows if r.get("supplier_id") == sid and r.get("unit_cost")]
    if own:
        return own[0]["unit_cost"], "high"
    generic = [r for r in rows if not r.get("supplier_id") and r.get("unit_cost")]
    if generic:
        return generic[0]["unit_cost"] * COUNTRY_FACTOR.get(prof.get("country") or "DE", 1.0), "medium"
    return q_price * QUOTE_FLOOR, "low"

